handle = func(origin /*string*/) {

    getTemplate = `import requests
import json


def poc_%s(url):
    headers = %s
    res = requests.%s(url=url, headers=headers, verify=False)
    return res.text

if __name__ == '__main__':
    url = "%s"
    result = poc_%s(url)
    print(result)
`

    postTemplate = `import requests
import json


def poc_%s(url):
    headers = %s
    res = requests.%s(url=url, headers=headers, data=%s, verify=False)
    return res.text

if __name__ == '__main__':
    url = "%s"
    result = poc_%s(url)
    print(result)
`

    postFileTemplate = `import requests
import json


def poc_%s(url):
    headers = %s
    # you should modify File content and Content-Type by yourself
    files = {"%s": ("%s", open("input your filename","rb").read(), "image/png")}
    res = requests.%s(url=url, headers=headers, files=files, verify=False)
    return res.text

if __name__ == '__main__':
    url = "%s"
    result = poc_%s(url)
    print(result)
`
    // 转换为json-post参数
    c = re.Compile(`^([^\[\]]+)(\[.*?\])$`)~

    headerToJson = func(v) {
        results = make(map[string]var)
        // header 转 json
        kvs = v.Split("\r\n")
        for kv in kvs {
            temp = kv.SplitN(": ", 2)
            if temp.Length() == 2 {
                key, value = str.Trim(temp[0],"\r\n"), str.Trim(temp[1],"\r\n")
                results[key] = value
            }
        }
        return results
    }

    parseCommonPostParam = func(v) {
        results = make(map[string]var)
        // post 转 json
        kvs = v.Split("&")
        for kv in kvs {
            temp = kv.SplitN("=", 2)
            key, value = str.Trim(temp[0],"\r\n"), str.Trim(temp[1],"\r\n")
            tempKeys = c.FindStringSubmatch(key)
            if len(tempKeys) > 0 {
                key = tempKeys[1]
                temp := tempKeys[2]
                temp = temp.Trim("[]")
                temp = temp.Split("][")
                if key not in results {
                    results[key] = make(map[string]var)
                }
                v = results[key]
                for t in temp[:-1] {
                    v[t] =  make(map[string]var)
                    v = v[t]
                }
                v[temp[-1]] = value
            } else {
                results[key] = value
            }
        }
        return results
    }

    header, body = poc.Split(origin)
    url = str.ExtractURLFromHTTPRequestRaw(header, false)[0]
    method = re.FindSubmatch(header, "(\\w+) \\/.* HTTP\\/\\d\\.\\d\\r\\n")[1]
    method = method.Lower()
    pure_header = re.ReplaceAll(header, "\\w+ \\/.* HTTP\\/\\d\\.\\d\\r\\nHost: [\\w\\.]+\\r\\n", nil)
    mapObj = headerToJson(pure_header)
    jsonHeader = json.dumps(mapObj)
    randName = "".Join(fuzz.Strings("{{randstr(5)}}"))

    if method == "get" {
        result = getTemplate % [randName, jsonHeader, method, url, randName]
        return result
    } else if method == "post"{
        data, result = nil, nil
        if body.StartsWith("{") {
            data = "json.dumps(%s)" % [body]
            result = postTemplate % [randName, jsonHeader, method, data, url, randName]
        } else if body.StartsWith("<") {
            data = body
            result = postTemplate % [randName, jsonHeader, method, data, url, randName]
        }else if header.Contains("multipart/form-data"){
            fileInfo = re.FindSubmatch(body, 'Content-Disposition: form-data; name=\\"(.*)\\"; filename=\\"(.*)\\"')
            fieldname, filename = fileInfo[1], fileInfo[2]
            result = postFileTemplate % [randName, jsonHeader, fieldname, filename, method, url, randName]
        }else {
            data = json.dumps(parseCommonPostParam(body))
            result = postTemplate % [randName, jsonHeader, method, data, url, randName]
        }
        return result
    }else {
        return "unknown method!"
    }   
}
